using System;using System.IO;using System.Linq;using System.Collections;using System.Reflection;using UnityEngine;using UnityEngine.UI;using Assets.Script.DynamicCards;using Cynthia.Card;
public static class MotionWork{public static void Run(){new GameObject("Actual collection scroll reproduction").AddComponent<ScrollReplay>();}}
public class ScrollReplay:MonoBehaviour{
const string W="C:/UnityProjects/LegacyGwent/work/DynamicCards/MotionIntegrity/ScrollAndFramingRepair/";
object F(object o,string n)=>o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);
bool Visible(DynamicCardView v)=>(bool)v.GetType().GetMethod("IsVisible",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(v,null);
void Snapshot(int step,EditorInfo e){var lib=DynamicCardLibrary.Instance;var views=FindObjectsOfType<DynamicCardView>();var visible=views.Where(Visible).ToArray();var q=(ICollection)F(lib,"queue");var parts=(IDictionary)F(lib,"parts");int bundles=0,leases=0;foreach(DictionaryEntry item in parts){var part=item.Value;var t=part.GetType();if(t.GetField("Bundle").GetValue(part)!=null)bundles++;leases+=(int)t.GetField("Leases").GetValue(part);}string line=DateTime.UtcNow.ToString("O")+" step="+step+" children="+e.ShowCardsContent.childCount+" views="+views.Length+" visible="+visible.Length+" live="+views.Count(v=>F(v,"model")!=null)+" queue="+q.Count+" creating="+F(lib,"creating")+" collecting="+F(lib,"collecting")+" bundles="+bundles+" leases="+leases+" memoryMB="+UnityEngine.Profiling.Profiler.GetTotalAllocatedMemoryLong()/1048576+"\n"+string.Join("\n",visible.Select(v=>(string)F(v,"artId")+" preview="+F(v,"preview")+" model="+(F(v,"model")!=null)+" camera="+(F(v,"renderCamera")!=null)+" age="+F(v,"age")));File.AppendAllText(W+"scroll-full-sweep.txt",line+"\n");}
IEnumerator Start(){Time.timeScale=1;File.WriteAllText(W+"scroll-full-sweep.txt","");var e=Resources.FindObjectsOfTypeAll<EditorInfo>().First(x=>x.gameObject.scene.IsValid());e.MainUI.SetActive(false);e.EditorUI.SetActive(true);e.OpenEditor(false);e.LeftSwitchMenu.anchoredPosition=new Vector2(-1700,0);e.RightSwitchMenu.anchoredPosition=new Vector2(1700,0);for(int page=0;page<25;page++){e.ShowCardScroll.onValueChanged.Invoke(0);yield return null;}e.ShowCardScroll.value=1;var first=e.ShowCardsContent.GetComponentsInChildren<CardShowInfo>().First();e.SelectSwitchUICard(first.CurrentCore);yield return new WaitForSecondsRealtime(10);Snapshot(0,e);for(int step=1;step<=50;step++){e.ShowCardScroll.value=1-step/50f;yield return null;yield return new WaitForSecondsRealtime(4);Snapshot(step,e);}yield return new WaitForSecondsRealtime(20);Snapshot(99,e);File.WriteAllText(W+"scroll-full-sweep-done.txt","DONE");Destroy(gameObject);}}
